use std::fs

fn main() {
    let limit: int = 200000
    let mut comp: Vec<bool> = []
    let mut cnt: Vec<int> = []
    let mut last: Vec<int> = []
    let mut i: int = 0
    while i <= limit {
        comp.push(false)
        cnt.push(0)
        last.push(0)
        i += 1
    }
    let mut p: int = 2
    while p <= limit {
        if !comp[p as usize] {
            let mut m: int = p * p
            while m <= limit {
                comp[m as usize] = true
                m += p
            }
        }
        p += 1
    }
    let mut c: int = 0
    let mut l: int = 0
    let mut k: int = 2
    while k <= limit {
        if !comp[k as usize] {
            c += 1
            l = k
        }
        cnt[k as usize] = c
        last[k as usize] = l
        k += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        let s = line.trim()
        if s == "" {
            continue
        }
        if first {
            first = false
            continue
        }
        let n: int = s.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${cnt[n as usize]} ${last[n as usize]}")
        }
    }
}

